// ============================================================================
// SUPABASE QUERIES SERVICE
// ============================================================================
// Manages public inquiries submitted through the contact page and displays
// them on the Admin Queries page with resolution tracking and mail utilities.
//
// Table Schema (PostgreSQL):
// create table public.queries (
//   id bigint generated by default as identity not null,
//   name character varying null,
//   email character varying null,
//   subject character varying null,
//   message character varying null,
//   resolved boolean default false,
//   constraint queries_pkey primary key (id)
// ) TABLESPACE pg_default;
// ============================================================================

import { supabase } from '../lib/supabaseClient';

const LOCAL_RESOLVED_STORAGE_KEY = 'technospark_resolved_queries_v1';

/**
 * SQL snippet to enable public insert, authenticated read/update,
 * and optional persistent resolved status column in Supabase.
 */
export const QUERIES_POLICY_SQL = `
-- Run this in your Supabase SQL Editor:
-- 1. Ensure RLS is disabled for full access:
ALTER TABLE public.queries DISABLE ROW LEVEL SECURITY;

-- 2. Optional: Add 'resolved' column to persist query status across devices:
ALTER TABLE public.queries ADD COLUMN IF NOT EXISTS resolved boolean DEFAULT false;

-- 3. If keeping RLS enabled instead, add these policies:
-- CREATE POLICY "Allow public insert on queries" ON public.queries FOR INSERT TO anon, authenticated WITH CHECK (true);
-- CREATE POLICY "Allow authenticated read on queries" ON public.queries FOR SELECT TO authenticated USING (true);
-- CREATE POLICY "Allow authenticated update on queries" ON public.queries FOR UPDATE TO authenticated USING (true);
`.trim();

/**
 * Retrieves the set of locally resolved query IDs from localStorage.
 */
export function getLocalResolvedSet() {
  try {
    const raw = localStorage.getItem(LOCAL_RESOLVED_STORAGE_KEY);
    if (!raw) return new Set();
    const parsed = JSON.parse(raw);
    return new Set(Array.isArray(parsed) ? parsed.map(String) : []);
  } catch (err) {
    console.warn('[queriesService] Error reading local resolved queries:', err);
    return new Set();
  }
}

/**
 * Updates localStorage with the resolution status for a given query ID.
 */
export function setLocalResolvedQuery(id, isResolved) {
  try {
    const set = getLocalResolvedSet();
    const idStr = String(id);
    if (isResolved) {
      set.add(idStr);
    } else {
      set.delete(idStr);
    }
    localStorage.setItem(LOCAL_RESOLVED_STORAGE_KEY, JSON.stringify(Array.from(set)));
  } catch (err) {
    console.warn('[queriesService] Error saving local resolved status:', err);
  }
}

/**
 * Normalizes a row from public.queries for reliable UI display.
 */
export function normalizeQuery(row, localResolvedSet = null) {
  if (!row) return null;
  const set = localResolvedSet || getLocalResolvedSet();
  const idStr = String(row.id);

  // Consider resolved if marked in DB column or present in local resolved set
  const isResolved =
    row.resolved === true ||
    row.is_resolved === true ||
    row.status === 'resolved' ||
    set.has(idStr);

  return {
    id: row.id,
    name: row.name || 'Anonymous User',
    email: row.email || '',
    subject: row.subject || 'General Inquiry',
    message: row.message || '(Empty message)',
    resolved: isResolved,
    status: isResolved ? 'resolved' : 'pending'
  };
}

/**
 * Fetches all query entries from Supabase public.queries.
 * Strictly sorts in DESCENDING order by ID so the latest query is on top.
 */
export async function getQueries() {
  try {
    const { data, error } = await supabase
      .from('queries')
      .select('*')
      .order('id', { ascending: false });

    if (error) {
      console.error('[queriesService] Error fetching queries from Supabase:', error);
      const isRls =
        error.code === '42501' ||
        (error.message && error.message.toLowerCase().includes('row-level security'));
      return { data: [], error, isRlsError: isRls };
    }

    const localSet = getLocalResolvedSet();
    const normalized = (data || []).map((r) => normalizeQuery(r, localSet));

    // Guarantee descending order by id (highest ID = newest query on top)
    normalized.sort((a, b) => Number(b.id) - Number(a.id));

    return { data: normalized, error: null };
  } catch (err) {
    console.error('[queriesService] Unexpected error in getQueries:', err);
    return { data: [], error: err };
  }
}

/**
 * Toggles or updates the resolved status of a query.
 * Persists to localStorage immediately and attempts database column update.
 */
export async function toggleQueryResolved(id, newStatus) {
  // 1. Immediately update localStorage so resolution is persistent
  setLocalResolvedQuery(id, newStatus);

  // 2. Try updating the database column if available in Supabase
  try {
    const { error } = await supabase
      .from('queries')
      .update({ resolved: newStatus })
      .eq('id', id);

    if (error) {
      // Column may not exist yet in Supabase schema, or RLS blocked UPDATE
      console.warn('[queriesService] Database column update skipped (persisted locally):', error.message);
      return { success: true, persistedInDb: false, error };
    }

    return { success: true, persistedInDb: true, error: null };
  } catch (err) {
    console.warn('[queriesService] Supabase update exception (persisted locally):', err);
    return { success: true, persistedInDb: false, error: err };
  }
}

/**
 * Inserts a new user inquiry into public.queries.
 * Used by the public Contact Page.
 *
 * Does not chain .select() to ensure unauthenticated/anonymous users
 * can submit without requiring SELECT read permissions.
 */
export async function submitContactQuery(queryData) {
  try {
    const payload = {
      name: (queryData.name || '').trim() || null,
      email: (queryData.email || '').trim() || null,
      subject: (queryData.subject || '').trim() || null,
      message: (queryData.message || '').trim() || null
    };

    const { error } = await supabase
      .from('queries')
      .insert([payload]);

    if (error) {
      console.error('[queriesService] Error submitting query to Supabase:', error);
      const isRls =
        error.code === '42501' ||
        (error.message && error.message.toLowerCase().includes('row-level security'));
      return { success: false, error, isRlsError: isRls };
    }

    return { success: true, error: null };
  } catch (err) {
    console.error('[queriesService] Unexpected error submitting query:', err);
    return { success: false, error: err };
  }
}
